import json,subprocess
p=subprocess.Popen(['/usr/local/bin/codex','app-server','--listen','stdio://'],stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.DEVNULL,text=True)
def send(v):p.stdin.write(json.dumps(v)+'\n');p.stdin.flush()
def call(i,m,a):
 send({'id':i,'method':m,'params':a})
 while True:
  v=json.loads(p.stdout.readline())
  if v.get('id')==i and 'method' not in v:return v
try:
 call(1,'initialize',{'clientInfo':{'name':'sdp_governance','version':'PGI3-C3-policy-check'},'capabilities':{'experimentalApi':False}});send({'method':'initialized','params':{}})
 v=call(2,'thread/start',{'cwd':'/tmp/sdp-pgi3-c3/trial/project','ephemeral':True,'sandbox':'read-only','approvalsReviewer':'user','approvalPolicy':{'granular':{'mcp_elicitations':True,'rules':False,'sandbox_approval':False,'request_permissions':False,'skill_approval':False}}})
 print(json.dumps({'error':v.get('error'),'threadCreated':'result' in v}))
finally:p.terminate();p.wait()

