package pgi3pilot

import "testing"

func TestNormalizeLabel(t *testing.T) {
	tests := []struct {
		name  string
		input string
		want  string
	}{
		{"empty", "", ""},
		{"unchanged", "KeepCase", "KeepCase"},
		{"ascii spaces", "  Keep  Case  ", "Keep  Case"},
		{"ascii whitespace", "\t\n\r\v\f KeepCase \t\n\r\v\f", "KeepCase"},
		{"unicode boundaries", "\u00a0\u2003\u202f\u3000KeepCase\u3000\u202f\u2003\u00a0", "KeepCase"},
		{"leading only", "\u0085\u2028KeepCase", "KeepCase"},
		{"trailing only", "KeepCase\u2029\u205f", "KeepCase"},
		{"whitespace only", " \t\n\u00a0\u2003\u202f\u3000", ""},
		{"interior preserved", "\u00a0 MiXeD  \t\n\u2003\u00a0Café 世界 \u3000", "MiXeD  \t\n\u2003\u00a0Café 世界"},
		{"non whitespace boundaries", "\u200bKeepCase\ufeff", "\u200bKeepCase\ufeff"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := NormalizeLabel(tt.input); got != tt.want {
				t.Errorf("NormalizeLabel(%q) = %q, want %q", tt.input, got, tt.want)
			}
		})
	}
}
